export default function draw(ctx, t) {
  const { width: w, height: h } = ctx.canvas;
  const s = t * 0.15;
  const a = s * 0.5;
  const cx = w / 2, cy = h / 2, r = Math.hypot(w, h) / 2;
  const g = ctx.createLinearGradient(
    cx + Math.cos(a) * r, cy + Math.sin(a) * r,
    cx - Math.cos(a) * r, cy - Math.sin(a) * r
  );
  const hue1 = 222 + Math.sin(s) * 8;
  const hue2 = 232 + Math.cos(s * 0.8) * 10;
  const l1 = 6 + Math.sin(s * 0.7) * 2;
  const l2 = 15 + Math.cos(s * 0.6) * 3;
  g.addColorStop(0, `hsl(${hue1}, 60%, ${l1}%)`);
  g.addColorStop(0.5, `hsl(${(hue1 + hue2) / 2}, 55%, ${(l1 + l2) / 2}%)`);
  g.addColorStop(1, `hsl(${hue2}, 50%, ${l2}%)`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

